<template><div class="user-admin-page"><header class="user-admin-toolbar"><div><span class="page-eyebrow">PRIVATE KITCHENS</span><h2>商户管理</h2><p>管理可服务多个家庭的私厨商户、负责人与私密邀请码。</p></div><button class="primary-button" @click="openCreate">新增商户</button></header><section class="user-table-panel"><div class="user-table-tools"><label class="user-search"><span>搜索</span><input v-model.trim="keyword" @keyup.enter="load" /></label><button class="ghost-button" @click="load">查询</button></div><div class="user-table-scroll"><table class="user-data-table"><thead><tr><th>商户</th><th>负责人</th><th>联系方式</th><th>家庭数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="m in merchants" :key="m.merchantId"><td><strong>{{m.name}}</strong><small>#{{m.merchantId}}</small></td><td>{{m.ownerUsername||'未设置'}}</td><td><strong>{{m.contactName||'-'}}</strong><small>{{m.contactPhone||'-'}}</small></td><td>{{m.familyCount}}</td><td><span class="status-pill">{{m.status}}</span></td><td><div class="inline-actions"><button class="text-button" @click="openEdit(m)">编辑</button><button class="text-button" @click="createCode(m)">邀请码</button><button class="text-button danger-text" @click="remove(m)">删除</button></div></td></tr></tbody></table></div></section><div v-if="dialog" class="user-modal-layer" @click.self="dialog=false"><section class="user-create-modal" role="dialog"><header><div><span class="page-eyebrow">MERCHANT</span><h3>{{form.merchantId?'编辑商户':'新增商户'}}</h3></div><button class="modal-close" @click="dialog=false">×</button></header><form @submit.prevent="save"><div class="modal-form-grid"><label class="form-field"><span>商户名称</span><input v-model.trim="form.name" required /></label><label class="form-field"><span>负责人用户</span><select v-model.number="form.ownerUserId" required><option :value="null">请选择</option><option v-for="u in users" :value="u.userId" :key="u.userId">{{u.nickname||u.username}} (@{{u.username}})</option></select></label><label class="form-field"><span>联系人</span><input v-model.trim="form.contactName" /></label><label class="form-field"><span>手机号</span><input v-model.trim="form.contactPhone" /></label><label class="form-field modal-form-grid__wide"><span>状态</span><select v-model="form.status"><option value="active">正常</option><option value="pending">待审核</option><option value="inactive">停用</option></select></label></div><footer><button type="button" class="ghost-button" @click="dialog=false">取消</button><button class="primary-button">保存</button></footer></form></section></div></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{listAdminUsers}from'../../api/admin-users';import{createAdminMerchant,deleteAdminMerchant,listAdminMerchants,rotateMerchantInvitationCode,updateAdminMerchant}from'../../api/admin-merchants';import{confirmAction}from'../../utils/dialog';import{notify}from'../../utils/feedback';const merchants=ref([]),users=ref([]),keyword=ref(''),dialog=ref(false),form=reactive({merchantId:null,name:'',ownerUserId:null,contactName:'',contactPhone:'',status:'active'});async function load(){merchants.value=await listAdminMerchants(keyword.value)}function openCreate(){Object.assign(form,{merchantId:null,name:'',ownerUserId:null,contactName:'',contactPhone:'',status:'active'});dialog.value=true}function openEdit(m){Object.assign(form,m);dialog.value=true}async function save(){const p={name:form.name,ownerUserId:form.ownerUserId,contactName:form.contactName,contactPhone:form.contactPhone,status:form.status};if(form.merchantId)await updateAdminMerchant(form.merchantId,p);else await createAdminMerchant(p);dialog.value=false;notify('商户已保存','success');await load()}async function createCode(m){const code=await rotateMerchantInvitationCode(m.merchantId);await confirmAction({title:'新商户邀请码',message:`${code}\n7 天内有效，请只分享给可信用户。`,confirmText:'我已记录'})}async function remove(m){if(!await confirmAction({title:`停用“${m.name}”`,message:'将停用商户权限和邀请码，历史订单与家庭保留。',danger:true,confirmText:'确认停用'}))return;await deleteAdminMerchant(m.merchantId);await load()}onMounted(async()=>{[users.value]=await Promise.all([listAdminUsers()]);await load()});</script>

